import {chooseSolidPaint,MAX_SOLID_PAINTS,FIRST_SOLID_PAINT} from './building-paint-colors.js?v=scenario-variable-manager-1';
export function solidPaletteHTML(){return `<section id="solidPaintPalette"><label>Solid paint color<input id="solidPaintColor" type="color" value="#4c6c90"></label><button type="button" id="chooseSolidPaint">Use this color</button><p class="fine">Choose a color, then paint a wall, roof or ground square. Up to 28 custom colors per building.</p><div class="material-swatches">${Array.from({length:MAX_SOLID_PAINTS},(_,i)=>`<button type="button" id="solidSwatch${i}" hidden aria-pressed="false"><span id="solidPreview${i}" aria-hidden="true"></span><span id="solidLabel${i}">Color ${i+1}</span></button>`).join('')}</div></section>`;}
export function mountSolidPalette(root,{get,material,applyColors,reserved=()=>[],status={}}){
 const $=id=>root.querySelector('#'+id),input=$('solidPaintColor'),choose=$('chooseSolidPaint'),section=$('solidPaintPalette'),buttons=Array.from({length:MAX_SOLID_PAINTS},(_,i)=>$('solidSwatch'+i));let key=null;
 function select(id){material.value=String(id);material.onchange?.();refresh();}
 function refresh(){const colors=get().paintColors||[],selected=Number(material.value),next=JSON.stringify(colors);if(selected>=FIRST_SOLID_PAINT&&!colors[selected-FIRST_SOLID_PAINT])material.value='0';const group=$('materialSet').value||'all';section.hidden=!['all','solid'].includes(group);input.disabled=choose.disabled=Boolean(material.disabled);
 buttons.forEach((b,i)=>{const color=colors[i];b.hidden=!color;b.disabled=Boolean(material.disabled);b.setAttribute('aria-pressed',String(Number(material.value)===i+FIRST_SOLID_PAINT));if(color&&key!==next){$('solidPreview'+i).innerHTML=`<svg width="80" height="64" viewBox="0 0 80 64"><rect width="80" height="64" fill="${color}"/></svg>`;$('solidLabel'+i).textContent=color;b.setAttribute('aria-label',`Solid paint ${color}`);}});if(Number(material.value)>=FIRST_SOLID_PAINT)input.value=colors[Number(material.value)-FIRST_SOLID_PAINT];key=next;
 }
 buttons.forEach((b,i)=>b.onclick=()=>{if(material.disabled||!get().paintColors?.[i])return;select(i+FIRST_SOLID_PAINT);});
 choose.onclick=()=>{if(material.disabled)return;try{const next=chooseSolidPaint(get(),input.value,reserved());applyColors(next.design.paintColors);select(next.material);status.textContent=`Selected solid paint ${next.design.paintColors[next.material-FIRST_SOLID_PAINT]}. Paint a surface, then Apply to save the building.`;}catch(error){status.textContent=error.message;}};
 refresh();return{refresh};
}
